export type VietlishCorpusCategory =
  | "calque"
  | "word_order"
  | "register"
  | "collocation"
  | "false_friend"
  | "literal_translation";

export type VietlishCorpusFrequency = "high" | "medium" | "low";

export type VietlishCorpusEntry = {
  vietlish: string;
  natural: string;
  sourcePattern: string;
  category: VietlishCorpusCategory;
  frequency: VietlishCorpusFrequency;
  context: string;
};

